181	func (m Model) parseVersion(versionOutput string) string {
182		if versionOutput == "" {
183			return ""
184		}
185	
186		isDocker := false
187		output := versionOutput
188	
189		// Handle docker versions (format: "docker:Version X.Y.Z...")
190		if strings.HasPrefix(versionOutput, "docker:") {
191			isDocker = true
192			output = strings.TrimPrefix(versionOutput, "docker:")
193			if output == "" {
194				return "(docker)"
195			}
196		}
197	
198		// Extract first line and try to find version number
199		lines := strings.Split(strings.TrimSpace(output), "\n")
200		if len(lines) == 0 {
201			if isDocker {
202				return "(docker)"
203			}
204			return ""
205		}
206	
207		firstLine := strings.TrimSpace(lines[0])
208		// Try to extract version pattern (e.g., "v0.50.1" or "0.50.1")
209		for _, part := range strings.Fields(firstLine) {
210			if looksLikeVersion(part) {
211				if isDocker {
212					return part + " (docker)"
213				}
214				return part
215			}
216		}
217	
218		// Return first line if no version pattern found (truncated)
219		result := theme.TruncateWidth(firstLine, versionDisplayWidth)
220		if isDocker {
221			return result + " (docker)"
222		}
223		return result
224	}
