48	// updateFindingsTable populates the findings table based on active tab and filters.
49	//
50	// The tab and the severity are this view's own filters, not the component's:
51	// they select which findings exist at all, where a FilterBar query narrows a
52	// list that is already settled. So the view filters and hands the result over.
53	func (m *Model) updateFindingsTable() {
54		if m.result == nil {
55			return
56		}
57	
58		findings := m.filterFindingsByTab()
59		if (m.activeTab == TabCVE || m.activeTab == TabLicense || m.activeTab == TabMisconfig) && m.severityFilter != "all" {
60			findings = m.filterFindingsBySeverity(findings)
61		}
62	
63		m.findingsTable.SetItems(findings)
64		// A change of tab or severity is a change of scope, not a shorter list, so
65		// the cursor goes back to the top. SetItems deliberately leaves it alone.
66		m.findingsTable.GotoTop()
67	}
