package security

import (
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/anthnel/devdesk/internal/scan"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// targetKind tells the two caches apart. It decides which loader `enter` uses
// and which TargetType a rescan runs with, so it is carried rather than
// re-derived from the name — an absolute path and a "repo:tag" are not reliably
// distinguishable, and guessing wrong scans a directory as an image.
type targetKind int

const (
	kindImage targetKind = iota
	kindRepo
)

// scanTarget is one row of the inventory: something that has been scanned, what
// the scan found, and when.
//
// Kind, the display name and whether a rescan is running now live on none of
// the cache entries, which is why the decoration goes on the row rather than
// being looked up from the model — the same reason imageRow exists. The columns
// are built once, in New, so their Cell functions have nothing to reach back
// into, and each count column sorts by the number it prints.
type scanTarget struct {
	Kind      targetKind
	Name      string // the cache key: "repo:tag", or the absolute repository path
	Counts    scan.SeverityCounts
	ScannedAt time.Time
	// Scanned is false between a ctrl+a purge and the scan that replaces it.
	// The target is still known — it is the counts that are not.
	Scanned      bool
	Scanning     bool
	Failed       bool
	SpinnerFrame string
}

// inventoryColumnCritical is the column the inventory opens sorted by,
// descending: the target with the most critical findings is the one the view
// exists to surface.
const inventoryColumnCritical = 1

// displayName is what the Target column shows: the image reference as it is
// cached, or the repository path with the home directory folded back to "~".
// The cache key stays the value everything else uses, so folding here cannot
// reach a loader or a scanner.
func (t scanTarget) displayName() string {
	if t.Kind == kindImage {
		return theme.IconDocker + " " + t.Name
	}
	return theme.IconWorkspace + " " + shortenHome(t.Name)
}

// shortenHome replaces the home directory prefix with "~". It is the inverse of
// the expansion the workspaces view does on the configured root.
func shortenHome(path string) string {
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		return path
	}
	rel, err := filepath.Rel(home, path)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return path
	}
	if rel == "." {
		return "~"
	}
	return "~" + string(filepath.Separator) + rel
}

// countColumn builds one of the four severity columns. A purged row prints "-"
// rather than "0": nothing was found and nothing is known are different answers,
// and zero is the one a user reads as "clean".
func countColumn(title string, get func(scan.SeverityCounts) int) datatable.Column[scanTarget] {
	return datatable.Column[scanTarget]{
		Title: title, MinWidth: 5,
		Cell: func(t scanTarget) string {
			if !t.Scanned {
				return "-"
			}
			return strconv.Itoa(get(t.Counts))
		},
		Less: func(a, b scanTarget) bool { return get(a.Counts) < get(b.Counts) },
	}
}

// inventoryScannedCell reports the scan state: the spinner while one runs, an
// error icon when the last attempt failed, otherwise how long ago it succeeded
// (Rule 127). Plain text throughout — Rule 122.
func inventoryScannedCell(t scanTarget) string {
	switch {
	case t.Scanning:
		return t.SpinnerFrame + "scanning"
	case t.Failed:
		return theme.IconError + " error"
	case t.Scanned:
		return theme.TimeAgo(t.ScannedAt)
	}
	return "-"
}

// inventoryColumns describes the inventory table.
func inventoryColumns() []datatable.Column[scanTarget] {
	return []datatable.Column[scanTarget]{
		{
			Title: "Target", MinWidth: 24, Flex: 1,
			Cell: func(t scanTarget) string { return t.displayName() },
			Less: func(a, b scanTarget) bool {
				return strings.ToLower(a.Name) < strings.ToLower(b.Name)
			},
			// The cache key, not the displayed name: a query for the full path of
			// a repository has to match the row that folds it to "~".
			Search: func(t scanTarget) string { return t.Name },
		},
		countColumn("CRIT", func(c scan.SeverityCounts) int { return c.Critical }),
		countColumn("HIGH", func(c scan.SeverityCounts) int { return c.High }),
		countColumn("MED", func(c scan.SeverityCounts) int { return c.Medium }),
		countColumn("LOW", func(c scan.SeverityCounts) int { return c.Low }),
		{
			Title: "Scanned", MinWidth: 14,
			Cell: inventoryScannedCell,
			Less: func(a, b scanTarget) bool { return a.ScannedAt.Before(b.ScannedAt) },
		},
	}
}

// newInventoryTable builds the inventory table.
func newInventoryTable() datatable.Model[scanTarget] {
	return datatable.New(datatable.Config[scanTarget]{
		Columns:    inventoryColumns(),
		SortColumn: inventoryColumnCritical,
		SortDesc:   true,
	})
}

package security

import (
	"context"
	"log"
	"runtime"
	"sort"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/scan"
)

// InventoryLoadedMsg carries the scanned targets read from the two caches.
type InventoryLoadedMsg struct {
	Targets []scanTarget
}

// InventoryResultLoadedMsg carries a full scan result read back for one target,
// or the error that says there is no longer a file to read.
type InventoryResultLoadedMsg struct {
	Name   string
	Result *scan.Result
	Err    error
}

// InventoryScanFinishedMsg reports one rescan launched from the inventory.
type InventoryScanFinishedMsg struct {
	Name   string
	Counts scan.SeverityCounts
	Err    error
}

// inventoryScanJob is one target to rescan.
type inventoryScanJob struct {
	Kind targetKind
	Name string
}

// loadInventoryCmd reads both scan caches for the current context.
//
// Only this context's entries are visible: the caches are bound to one at
// construction, which is what stops the inventory listing what another context
// scanned (§0b).
func loadInventoryCmd() tea.Cmd {
	return func() tea.Msg {
		contextName := config.CurrentContextName()
		targets := make([]scanTarget, 0)

		if c, err := cache.NewImageScanCache(contextName); err != nil {
			log.Printf("ERROR [security/inventory] open image scan cache: %v", err)
		} else {
			for name, entry := range c.GetAll() {
				targets = append(targets, scanTarget{
					Kind: kindImage, Name: name, Scanned: true,
					Counts: scan.SeverityCounts{
						Critical: entry.Critical, High: entry.High,
						Medium: entry.Medium, Low: entry.Low,
					},
					ScannedAt: entry.ScannedAt,
				})
			}
		}

		if c, err := cache.NewWorkspaceScanCache(contextName); err != nil {
			log.Printf("ERROR [security/inventory] open workspace scan cache: %v", err)
		} else {
			for path, entry := range c.GetAll() {
				targets = append(targets, scanTarget{
					Kind: kindRepo, Name: path, Scanned: true,
					Counts: scan.SeverityCounts{
						Critical: entry.Critical, High: entry.High,
						Medium: entry.Medium, Low: entry.Low,
					},
					ScannedAt: entry.ScannedAt,
				})
			}
		}

		// Both caches are maps, so their range order is deliberately random.
		// Settling one here means the table's stable sort has something stable
		// underneath it, and two rows equal on the sort column keep their order
		// between refreshes instead of swapping.
		sort.Slice(targets, func(i, j int) bool {
			return strings.ToLower(targets[i].Name) < strings.ToLower(targets[j].Name)
		})
		return InventoryLoadedMsg{Targets: targets}
	}
}

// loadInventoryResultCmd reads back the full result stored for one target
// (Rule 126: opening a scanned row reads the cache, it never scans).
func loadInventoryResultCmd(target scanTarget) tea.Cmd {
	kind, name := target.Kind, target.Name
	return func() tea.Msg {
		var result *scan.Result
		var err error
		if kind == kindImage {
			result, err = cache.LoadImageScanResult(name)
		} else {
			result, err = cache.LoadWorkspaceScanResult(name)
		}
		if err != nil {
			log.Printf("ERROR [security/inventory] load result %s: %v", name, err)
		}
		return InventoryResultLoadedMsg{Name: name, Result: result, Err: err}
	}
}

// purgeInventoryCmd removes the cached entries and stored results for the given
// targets. Rule 126: ctrl+a purges before rescanning, where ctrl+s overwrites.
func purgeInventoryCmd(jobs []inventoryScanJob) tea.Cmd {
	if len(jobs) == 0 {
		return nil
	}
	return func() tea.Msg {
		contextName := config.CurrentContextName()
		imageCache, imageErr := cache.NewImageScanCache(contextName)
		repoCache, repoErr := cache.NewWorkspaceScanCache(contextName)
		for _, job := range jobs {
			if job.Kind == kindImage {
				if imageErr == nil {
					_ = imageCache.Delete(job.Name)
				}
				continue
			}
			if repoErr == nil {
				_ = repoCache.Delete(job.Name)
			}
			_ = cache.DeleteWorkspaceScanResult(job.Name)
		}
		return nil
	}
}

// rescanCmd scans every job through a worker pool of NumCPU/2, the size the
// images and workspaces lists already use.
func rescanCmd(jobs []inventoryScanJob, opts scan.ScanOptions) tea.Cmd {
	sem := make(chan struct{}, max(runtime.NumCPU()/2, 1))
	cmds := make([]tea.Cmd, len(jobs))
	for i, job := range jobs {
		cmds[i] = rescanOneCmd(job, opts, sem)
	}
	return tea.Batch(cmds...)
}

// rescanOneCmd rescans a single target and writes the result through to both
// the counts cache and the stored result, so the row and `enter` agree.
func rescanOneCmd(job inventoryScanJob, opts scan.ScanOptions, sem chan struct{}) tea.Cmd {
	return func() tea.Msg {
		sem <- struct{}{}
		defer func() { <-sem }()

		targetType := scan.TargetImage
		if job.Kind == kindRepo {
			targetType = scan.TargetDirectory
		}
		result, err := scan.NewScanner(opts).Scan(context.Background(), job.Name, targetType)
		if err != nil {
			log.Printf("ERROR [security/inventory] rescan %s: %v", job.Name, err)
			return InventoryScanFinishedMsg{Name: job.Name, Err: err}
		}
		// Scan() reports scanner failures in result.Errors rather than as an
		// error. Every scanner having failed is not an empty inventory row, it
		// is a row that could not be produced.
		if len(result.Errors) > 0 && result.TotalFindings() == 0 {
			combined := strings.Join(result.Errors, "; ")
			log.Printf("ERROR [security/inventory] rescan errors for %s: %s", job.Name, combined)
			return InventoryScanFinishedMsg{Name: job.Name, Err: errScanFailed(combined)}
		}

		storeRescan(job, result)
		return InventoryScanFinishedMsg{Name: job.Name, Counts: result.Counts}
	}
}

// storeRescan writes a finished rescan to the cache its kind belongs to.
func storeRescan(job inventoryScanJob, result *scan.Result) {
	contextName := config.CurrentContextName()
	if job.Kind == kindImage {
		if c, err := cache.NewImageScanCache(contextName); err == nil {
			_ = c.Set(job.Name, cache.ImageScanEntry{
				Critical: result.Counts.Critical, High: result.Counts.High,
				Medium: result.Counts.Medium, Low: result.Counts.Low,
				ScannedAt: result.EndTime,
			})
		}
		if err := cache.SaveImageScanResult(job.Name, result); err != nil {
			log.Printf("ERROR [security/inventory] save image result %s: %v", job.Name, err)
		}
		return
	}
	if c, err := cache.NewWorkspaceScanCache(contextName); err == nil {
		_ = c.Set(job.Name, cache.WorkspaceScanEntry{
			RepoPath: job.Name,
			Critical: result.Counts.Critical, High: result.Counts.High,
			Medium: result.Counts.Medium, Low: result.Counts.Low,
			Sensitive: hasScanSource(result, "gitleaks"),
			ScannedAt: result.EndTime,
		})
	}
